            }
            Acc{text: "开工" on_click: || runAction("startProgress")}
            Bar{text: "记录处置" on_click: || runAction("recordProgress")}
            Bar{text: "上传证据" on_click: || addEvidence()}
            Bar{text: "隔离证据" on_click: || quarantineEvidence()}
        }

        // Step 6 — 完工与验收
        View{width: Fill height: Fit flow: Down spacing: 10 padding: 16
                draw_bg.color: surface draw_bg.border_radius: 14.0 draw_bg.border_size: 1.0 draw_bg.border_color: border
            View{width: Fill height: Fit flow: Down spacing: 4
                Label{text: "STEP 6" draw_text.color: accent draw_text.text_style.font_size: 10 draw_text.text_style.font_weight: 700}
                Label{text: "完工与独立验收" draw_text.color: ink draw_text.text_style.font_size: 14 draw_text.text_style.font_weight: 600}
                Label{text: "另一主体验收，承接者不能自验" draw_text.color: secondary draw_text.text_style.font_size: 11 max_lines: 2}
            }
            Acc{text: "提交完工" on_click: || runAction("submitCompletion")}
            Acc{text: "验收 → COMPLETED" on_click: || runAction("acceptCompletion")}
            Danger{text: "退回重做" on_click: || runAction("rejectCompletion")}
        }

        // Step 7 — 其他
        View{width: Fill height: Fit flow: Down spacing: 10 padding: 16
                draw_bg.color: surface draw_bg.border_radius: 14.0 draw_bg.border_size: 1.0 draw_bg.border_color: border
            View{width: Fill height: Fit flow: Down spacing: 4
                Label{text: "终止与改派" draw_text.color: secondary draw_text.text_style.font_size: 10 draw_text.text_style.font_weight: 700}
                Label{text: "终止任务 / 经理改派" draw_text.color: ink draw_text.text_style.font_size: 14 draw_text.text_style.font_weight: 600}
            }
            Danger{text: "取消任务" on_click: || runAction("cancel")}
            Bar{text: "改派" on_click: || runAction("reassign")}
        }
    }

    // ════ 任务清单 ════
    View{width: Fill height: Fit flow: Down spacing: 8 padding: Inset{top: 16 bottom: 16 left: 16 right: 16}
        Label{text: "任务清单（按主体可见）" draw_text.color: secondary draw_text.text_style.font_size: 11}
        ScrollYView{width: Fill height: 160 flow: Down spacing: 6
            for i t in TASKS {
                if visible(t, me()) {
                    View{width: Fill height: Fit flow: Down spacing: 4 padding: 12
                            draw_bg.color: surface draw_bg.border_radius: 12.0 draw_bg.border_size: 1.0 draw_bg.border_color: border
                        Label{width: Fill text: t.status
                            draw_text.color: accent draw_text.text_style.font_size: 10 draw_text.text_style.font_weight: 600}
                        Label{width: Fill text: t.id
                            draw_text.color: ink draw_text.text_style.font_size: 12}
                        Label{width: Fill text: "承接：" + whoLabel(t) + "  ·  " + apptLine(t)
                            draw_text.color: secondary draw_text.text_style.font_size: 11 max_lines: 1}
                    }
                }
            }
        }
    }

    // ════ 状态条 ════
    View{width: Fill height: Fit flow: Down spacing: 4 padding: Inset{top: 12 bottom: 16 left: 16 right: 16}
            draw_bg.color: #x0A1112
        Label{width: Fill text: "📍 " + STATE.status max_lines: 3
            draw_text.color: ink draw_text.text_style.font_size: 12}
        Label{width: Fill text: factsLine() max_lines: 2
            draw_text.color: secondary draw_text.text_style.font_size: 11}
    }
}
